"""Surgical live Alpaca discretionary-close race fix.

Run from repository root on fix/heartbeat-runtime-root-causes-20260728.
This intentionally does not alter emergency flatten_all semantics.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ALPACA = ROOT / "backend/app/brokers/alpaca.py"
TEST = ROOT / "backend/tests/test_live_close_cancel_confirmation.py"


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        print(f"already applied: {label}")
        return text
    if old not in text:
        raise RuntimeError(f"anchor not found for {label}")
    return text.replace(old, new, 1)


text = ALPACA.read_text(encoding="utf-8")
old = '''    async def close_position(self, symbol: str, reason: str = "manual") -> Order | None:\n        try:\n            # First, fetch and cancel any outstanding open orders for this symbol to release held quantities\n            try:\n                from alpaca.trading.requests import GetOrdersRequest\n                open_orders = await _call(\n                    self._client.get_orders,\n                    GetOrdersRequest(status="open", symbols=[symbol.upper()]),\n                    label=f"get_orders/close_position/{symbol}"\n                )\n                for o in open_orders:\n                    await _call(self._client.cancel_order_by_id, str(o.id), label=f"cancel_order/{o.id}")\n                    applog.info("broker.alpaca", f"Cancelled outstanding open order {o.id} for {symbol} to release held qty")\n            except Exception as e:\n                applog.warning("broker.alpaca", f"Failed to cancel open orders for {symbol} before close: {e}")\n\n            raw = await _call(self._client.close_position, symbol.upper(), label=f"close_position/{symbol}")\n            self._meta[str(raw.id)] = ("engine", reason)\n            applog.trade("broker.alpaca", f"Closing {symbol} ({reason})")\n            return self._to_order(raw)\n        except BrokerTimeoutError:\n            applog.warning("broker.alpaca", f"close_position {symbol} timed out; state is ambiguous")\n            return None\n        except Exception as exc:  # noqa: BLE001\n            applog.warning("broker.alpaca", f"close {symbol} failed: {exc}")\n'''
new = '''    async def close_position(self, symbol: str, reason: str = "manual") -> Order | None:\n        \"\"\"Discretionary close with a fail-closed broker-order handshake.\n\n        Native bracket children reserve position quantity at Alpaca.  Never submit\n        a second discretionary market close while any competing exit remains open\n        or cancellation state is ambiguous.  Emergency/EOD liquidation continues\n        to use flatten_all(), whose stronger semantics are intentionally unchanged.\n        \"\"\"\n        sym = symbol.upper()\n        try:\n            from alpaca.trading.requests import GetOrdersRequest\n\n            open_orders = await _call(\n                self._client.get_orders,\n                GetOrdersRequest(status="open", symbols=[sym]),\n                label=f"get_orders/close_position/{sym}",\n            )\n            for o in open_orders:\n                oid = str(o.id)\n                try:\n                    await _call(self._client.cancel_order_by_id, oid, label=f"cancel_order/{oid}")\n                except BrokerTimeoutError:\n                    applog.warning(\n                        "broker.alpaca",\n                        f"Refusing discretionary close for {sym}: cancellation of {oid} is ambiguous",\n                    )\n                    return None\n                except Exception as exc:  # noqa: BLE001\n                    applog.warning(\n                        "broker.alpaca",\n                        f"Refusing discretionary close for {sym}: failed to cancel competing order {oid}: {exc}",\n                    )\n                    return None\n\n            # Cancellation acknowledgement is not enough: re-read broker truth.\n            # Alpaca may still expose a child as open while cancellation settles.\n            remaining = await _call(\n                self._client.get_orders,\n                GetOrdersRequest(status="open", symbols=[sym]),\n                label=f"verify_orders/close_position/{sym}",\n            )\n            if remaining:\n                ids = ",".join(str(o.id) for o in remaining)\n                applog.warning(\n                    "broker.alpaca",\n                    f"Refusing discretionary close for {sym}: competing exits still open after cancel ({ids})",\n                )\n                return None\n\n            # Re-read the authoritative position after cancellation.  A bracket leg\n            # may have filled during the handshake, in which case there is nothing\n            # left for us to close and submitting a new order could reverse exposure.\n            positions = await _call(self._client.get_all_positions, label=f"verify_position/close_position/{sym}")\n            live_position = next((p for p in positions if str(getattr(p, "symbol", "")).upper() == sym), None)\n            if live_position is None or abs(float(getattr(live_position, "qty", 0.0) or 0.0)) <= 1e-9:\n                applog.info("broker.alpaca", f"Skipping discretionary close for {sym}: broker position already flat")\n                return None\n\n            raw = await _call(self._client.close_position, sym, label=f"close_position/{sym}")\n            self._meta[str(raw.id)] = ("engine", reason)\n            applog.trade("broker.alpaca", f"Closing {sym} ({reason})")\n            return self._to_order(raw)\n        except BrokerTimeoutError:\n            applog.warning("broker.alpaca", f"close_position {sym} timed out; state is ambiguous")\n            return None\n        except Exception as exc:  # noqa: BLE001\n            applog.warning("broker.alpaca", f"close {sym} failed: {exc}")\n            return None\n'''
text = replace_once(text, old, new, "live close cancel-confirmation handshake")
ALPACA.write_text(text, encoding="utf-8")

TEST.write_text('''from unittest.mock import MagicMock, patch\n\nimport pytest\n\nfrom app.brokers.alpaca import AlpacaBroker\nfrom app.brokers.base import BrokerTimeoutError\n\n\ndef _broker():\n    with patch("app.brokers.alpaca.AlpacaBroker.__init__", lambda self, *a, **kw: None):\n        b = AlpacaBroker.__new__(AlpacaBroker)\n    b.is_paper = False\n    b._client = MagicMock()\n    b._meta = {}\n    b._symbol_strategies = {}\n    return b\n\n\n@pytest.mark.asyncio\nasync def test_discretionary_close_aborts_when_cancel_is_ambiguous():\n    b = _broker()\n    child = MagicMock(id="tp-1")\n    b._client.get_orders.return_value = [child]\n    b._client.cancel_order_by_id.side_effect = BrokerTimeoutError("timeout")\n    b._client.close_position = MagicMock()\n    assert await b.close_position("AAPL", reason="harvest") is None\n    b._client.close_position.assert_not_called()\n\n\n@pytest.mark.asyncio\nasync def test_discretionary_close_aborts_until_broker_confirms_no_competing_exit():\n    b = _broker()\n    child = MagicMock(id="stop-1")\n    b._client.get_orders.side_effect = [[child], [child]]\n    b._client.cancel_order_by_id.return_value = None\n    b._client.close_position = MagicMock()\n    assert await b.close_position("AAPL", reason="harvest") is None\n    b._client.close_position.assert_not_called()\n\n\n@pytest.mark.asyncio\nasync def test_discretionary_close_does_not_reverse_if_bracket_filled_during_cancel():\n    b = _broker()\n    child = MagicMock(id="tp-1")\n    b._client.get_orders.side_effect = [[child], []]\n    b._client.cancel_order_by_id.return_value = None\n    b._client.get_all_positions.return_value = []\n    b._client.close_position = MagicMock()\n    assert await b.close_position("AAPL", reason="harvest") is None\n    b._client.close_position.assert_not_called()\n''', encoding="utf-8")

print("Applied live discretionary close cancel-confirmation fix.")
